4	struct TodayView: View {
5	    @EnvironmentObject private var store: AppStore
6	    @State private var isCaptureFocused = false
7	
8	    var body: some View {
9	        NavigationStack {
10	            ScrollViewReader { proxy in
11	                ScrollView {
12	                    VStack(alignment: .leading, spacing: DS.sectionSpacing) {
13	                        header
14	                            .id(TodayScrollAnchor.top)
15	                        loopProgress {
16	                            withAnimation(.easeInOut(duration: 0.24)) {
17	                                proxy.scrollTo(TodayScrollAnchor.top, anchor: .top)
18	                            }
19	                        }
20	
21	                        switch store.todayDraft.state {
22	                        case .verifyYesterday:
23	                            verifyYesterdaySection
24	                        case .capture:
25	                            captureSection
26	                        case .organizing:
27	                            organizingSection
28	                        case .reviewCards:
29	                            reviewCardsSection
30	                        case .selectMode:
31	                            selectModeSection
32	                        case .selectLens:
33	                            selectLensSection
34	                        case .answerQuestions:
35	                            answerQuestionsSection
36	                        case .reviewQuests:
37	                            reviewQuestsSection
38	                        case .extractPrinciple:
39	                            extractPrincipleSection
40	                        case .sessionComplete:
41	                            sessionCompleteSection
42	                        }
43	                    }
44	                    .padding(.horizontal, DS.pagePadding)
45	                    .padding(.top, 12)
46	                    .padding(.bottom, 112)
47	                }
48	                .scrollIndicators(.hidden)
49	                .pageBackground()
50	                .safeAreaInset(edge: .bottom, spacing: 0) {
51	                    actionRow
52	                }
53	            }
54	        }
55	    }
56	
57	    // MARK: - Header
58	
59	    private var header: some View {
60	        VStack(alignment: .leading, spacing: 8) {
61	            Text(store.todayDraft.date, style: .date)
62	                .font(.caption)
63	                .foregroundStyle(DS.mutedInk)
64	                .textCase(.uppercase)
65	
66	            HStack(alignment: .firstTextBaseline) {
67	                Text(store.currentStateTitle)
68	                    .font(.system(size: 31, weight: .bold, design: .rounded))
69	                    .foregroundStyle(DS.ink)
70	
71	                Spacer()
72	
73	                if store.todayDraft.hasSelectedSessionMode {
74	                    Text(store.todayDraft.sessionMode.title)
75	                        .font(.caption.weight(.semibold))
76	                        .foregroundStyle(DS.accent)
77	                        .padding(.horizontal, 10)
78	                        .padding(.vertical, 5)
79	                        .background(DS.accent.opacity(0.08), in: Capsule())
80	                }
81	            }
82	
83	            if !store.todayLoopMessage.isEmpty {
84	                VStack(alignment: .leading, spacing: 8) {
85	                    Text(store.todayLoopMessage)
86	                        .font(.footnote)
87	                        .foregroundStyle(DS.caution)
88	                    if store.canRetryCurrentAI {
89	                        Button {
90	                            store.retryCurrentAIStep()
91	                        } label: {
92	                            Label("重试 AI", systemImage: "arrow.clockwise")
93	                        }
94	                        .font(.footnote.weight(.semibold))
95	                        .buttonStyle(.bordered)
96	                        .controlSize(.small)
97	                    }
98	                }
99	                .padding(.top, 2)
100	            }
101	        }
102	    }
103	
104	    private func loopProgress(scrollToTop: @escaping () -> Void) -> some View {
105	        VStack(alignment: .leading, spacing: 8) {
106	            HStack(spacing: 6) {
107	                ForEach(DailyLoopState.allCases) { state in
108	                    Button {
109	                        if store.canNavigateTodayLoop(to: state) {
110	                            withAnimation(.easeInOut(duration: 0.2)) {
111	                                store.navigateTodayLoop(to: state)
112	                                scrollToTop()
113	                            }
114	                        } else {
115	                            scrollToTop()
116	                        }
117	                    } label: {
118	                        Capsule()
119	                            .fill(progressColor(for: state))
120	                            .frame(height: 8)
121	                            .opacity(store.canNavigateTodayLoop(to: state) || state == store.todayDraft.state ? 1 : 0.55)
122	                    }
123	                    .buttonStyle(.plain)
124	                    .accessibilityLabel("回到\(state.title)")
125	                    .accessibilityHint(store.canNavigateTodayLoop(to: state) ? "点按回到该步骤编辑" : "该步骤暂不可返回")
126	                }
127	            }
128	
129	            Text(progressCaption)
130	                .font(.caption)
131	                .foregroundStyle(DS.mutedInk)
132	        }
133	        .padding(.top, 2)
134	        .contentShape(Rectangle())
135	        .onTapGesture(perform: scrollToTop)
136	        .accessibilityElement(children: .combine)
137	        .accessibilityLabel("今日流程进度")
138	        .accessibilityHint("点按返回今日顶部")
139	    }
140	
141	    // MARK: - Verify Yesterday
142	
143	    // Purpose: Close yesterday's loop before starting fresh
144	    // Design: Warm, reflective - not a form, a moment of honesty
145	    private var verifyYesterdaySection: some View {
146	        VStack(alignment: .leading, spacing: 14) {
147	            stepLabel("先回看昨天", subtitle: "用一个真实结果校准昨天的判断。")
148	
149	            if let quest = store.mainQuest ?? store.quests.first {
150	                VStack(alignment: .leading, spacing: 6) {
151	                    Text("昨日主线任务")
152	                        .font(.caption)
153	                        .foregroundStyle(.secondary)
154	                    Text(quest.title)
155	                        .font(.body.weight(.medium))
156	                }
157	                .questSurface(isMain: true)
158	            }
159	
160	            VStack(alignment: .leading, spacing: 8) {
161	                Text("完成了吗？")
162	                    .font(.subheadline.weight(.medium))
163	                HStack(spacing: 10) {
164	                    ForEach(YesterdayCompletion.allCases) { completion in
165	                        choiceChip(
166	                            title: completion.title,
167	                            isSelected: store.todayDraft.yesterdayCompletion == completion,
168	                            action: { store.selectYesterdayCompletion(completion) }
169	                        )
170	                    }
171	                }
172	            }
173	
174	            VStack(alignment: .leading, spacing: 8) {
175	                Text("实际价值？")
176	                    .font(.subheadline.weight(.medium))
177	                HStack(spacing: 10) {
178	                    ForEach(YesterdayValueRating.allCases) { rating in
179	                        choiceChip(
180	                            title: rating.title,
181	                            isSelected: store.todayDraft.yesterdayValueRating == rating,
182	                            action: { store.selectYesterdayValueRating(rating) }
183	                        )
184	                    }
185	                }
186	            }
187	        }
188	    }
189	
190	    // MARK: - Capture
191	
192	    // Purpose: Raw dump of today's messy thoughts
193	    // Design: Generous text area, inviting, feels like opening a notebook
194	    private var captureSection: some View {
195	        VStack(alignment: .leading, spacing: 14) {
196	            stepLabel("今天发生了什么？", subtitle: "先收集原始材料，不急着写成文章。")
197	
198	            CaptureTextView(text: Binding(
199	                get: { store.todayDraft.rawText },
200	                set: { store.updateTodayCapture($0) }
201	            ), isFocused: $isCaptureFocused)
202	            .frame(minHeight: 220)
203	            .background(Color(.systemBackground), in: RoundedRectangle(cornerRadius: DS.cornerRadius, style: .continuous))
204	            .overlay(
205	                RoundedRectangle(cornerRadius: DS.cornerRadius, style: .continuous)
206	                    .stroke(Color.primary.opacity(0.06), lineWidth: 1)
207	                    .allowsHitTesting(false)
208	            )
209	
210	            HStack(spacing: 10) {
211	                Button {
212	                    pasteClipboardIntoCapture()
213	                } label: {
214	                    Label("粘贴剪贴板", systemImage: "doc.on.clipboard")
215	                }
216	                .font(.footnote.weight(.semibold))
217	                .buttonStyle(.bordered)
218	
219	                Button {
220	                    isCaptureFocused = true
221	                } label: {
222	                    Label("开始输入", systemImage: "keyboard")
223	                }
224	                .font(.footnote.weight(.semibold))
225	                .buttonStyle(.bordered)
