639	    private func progressColor(for state: DailyLoopState) -> Color {
640	        let states = DailyLoopState.allCases
641	        guard
642	            let currentIndex = states.firstIndex(of: store.todayDraft.state),
643	            let stateIndex = states.firstIndex(of: state)
644	        else {
645	            return Color.primary.opacity(0.08)
646	        }
647	        if stateIndex < currentIndex {
648	            return DS.accent.opacity(0.55)
649	        }
650	        if stateIndex == currentIndex {
651	            return DS.accent
652	        }
653	        return Color.primary.opacity(0.08)
654	    }
