1120	            guard textView.markedTextRange == nil else { return }
1121	            text = textView.text
1122	        }
1123	
1124	        func textViewDidBeginEditing(_ textView: UITextView) {
1125	            isFocused = true
1126	        }
1127	
1128	        func textViewDidEndEditing(_ textView: UITextView) {
1129	            if textView.markedTextRange == nil {
1130	                text = textView.text
