    var title: String {
        switch self {
        case .week: return "周"
        case .month: return "月"
        case .year: return "年"
        }
    }

    var titleForPeriod: String {
        switch self {
        case .week: return "按周浏览"
        case .month: return "按月浏览"
        case .year: return "按年浏览"
        }
    }
}

private enum HistoryEvidenceKind: String, CaseIterable, Identifiable {
